# integration.sh — csm -m and csm -F on whole trees: repositories, session
# directories and .claude.json, all built below WORKDIR.
#
# Usage: integration.sh CSM WORKDIR

CSM=$(cd "$(dirname "$1")" && pwd)/$(basename "$1")
WORK=$(cd "$2" && pwd -P)
CHECKS=0
FAILURES=0

LC_ALL=en_US.UTF-8
CSM_CLAUDE_PROCESS=csm-no-such-process
export LC_ALL CSM_CLAUDE_PROCESS

# ok DESCRIPTION COMMAND... — the command must succeed.
ok() {
	DESC=$1
	shift
	CHECKS=$((CHECKS + 1))
	if ! "$@"
	then
		FAILURES=$((FAILURES + 1))
		echo "integration: $SCENARIO: $DESC"
	fi
}

# run STATUS ARG... — runs csm, keeps its output in OUT and checks the status.
run() {
	WANT=$1
	shift
	OUT=$("$CSM" "$@" 2>&1)
	GOT=$?
	CHECKS=$((CHECKS + 1))
	if [ "$GOT" -ne "$WANT" ]
	then
		FAILURES=$((FAILURES + 1))
		echo "integration: $SCENARIO: csm $*: status $GOT, want $WANT: $OUT"
	fi
}

has_output() {
	printf '%s\n' "$OUT" | grep -q -- "$1"
}

lacks_output() {
	! has_output "$1"
}

contains() {
	grep -q -F -- "$2" "$1"
}

lacks() {
	! grep -q -F -- "$2" "$1"
}

# The session directory name of an ASCII path, as Claude Code makes it.
enc() {
	printf '%s' "$1" | LC_ALL=C sed 's/[^A-Za-z0-9]/-/g'
}

# scenario NAME — a fresh tree with its own HOME and Claude Code config.
scenario() {
	SCENARIO=$1
	S=$WORK/$1
	mkdir -p "$S/home/.claude/projects"
	HOME=$S/home
	CLAUDE_CONFIG_DIR=$HOME/.claude
	PROJ=$CLAUDE_CONFIG_DIR/projects
	CONFIG=$CLAUDE_CONFIG_DIR/.claude.json
	export HOME CLAUDE_CONFIG_DIR
	cd "$S" || exit 1
}

# session FILE CWD... — a session file with one message line per cwd.
session() {
	FILE=$1
	shift
	mkdir -p "$(dirname "$FILE")"
	printf '{"type":"permission-mode","permissionMode":"default"}\n' > "$FILE"
	for CWD in "$@"
	do
		printf '{"type":"user","cwd":"%s","message":{"cwd":"%s"}}\n' \
		    "$CWD" "$CWD" >> "$FILE"
	done
}

# An mtime from 2020, and stamps just before and after it.
old_time() {
	touch -t 202001020304 "$@"
}

stamps() {
	touch -t 202001020303 "$WORK/before"
	touch -t 202001020305 "$WORK/after"
}

kept_time() {
	[ -n "$(find "$1" -newer "$WORK/before")" ] &&
	    [ -z "$(find "$1" -newer "$WORK/after")" ]
}

# The trash of csm for the current HOME and XDG_DATA_HOME (4.6).
trash_dir() {
	case $(uname)
	in
	Darwin)
		echo "$HOME/Library/Application Support/csm/trash"
		;;
	*)
		echo "$XDG_DATA_HOME/csm/trash"
		;;
	esac
}

# device FILE — the number of the device that holds FILE (stat differs).
device() {
	case $(uname)
	in
	Darwin|*BSD)
		stat -f %d "$1"
		;;
	*)
		stat -c %d "$1"
		;;
	esac
}

# The whole tree, names and contents, for comparing before and after.
snapshot() {
	(cd "$1" && find . -print | LC_ALL=C sort &&
	    find . -type f -exec cksum {} + | LC_ALL=C sort)
}

stamps

# Move with sessions of subdirectories; repo2 must not follow repo.
scenario move
mkdir -p a/repo/sub a/repo2 b
OLD=$PROJ/$(enc "$S/a/repo")
OLD_SUB=$PROJ/$(enc "$S/a/repo/sub")
OTHER=$PROJ/$(enc "$S/a/repo2")
NEW=$PROJ/$(enc "$S/b/repo")
NEW_SUB=$PROJ/$(enc "$S/b/repo/sub")
session "$OLD/s1.jsonl" "$S/a/repo" "$S/a/repo/sub" /elsewhere
printf '{"cwd":"%s","toolUseResult":{"persistedOutputPath":"%s/s1/tool-results/x.txt"}}\n' \
    "$S/a/repo" "$OLD" >> "$OLD/s1.jsonl"
printf '{"type":"relocated","sessionId":"s1","relocatedCwd":"%s"}\n' \
    "$S/a/repo" >> "$OLD/s1.jsonl"
printf '{"cwd":"%s"' "$S/a/repo" >> "$OLD/s1.jsonl"
session "$OLD/s1/subagents/agent-1.jsonl" "$S/a/repo/sub"
mkdir -p "$OLD/s1/tool-results" "$OLD/memory"
echo result > "$OLD/s1/tool-results/x.txt"
echo note > "$OLD/memory/MEMORY.md"
session "$OLD_SUB/s2.jsonl" "$S/a/repo/sub"
session "$OTHER/s3.jsonl" "$S/a/repo2"
printf '{"projects":{"%s":{"t":1},"%s/sub":{},"%s":{}},"githubRepoPaths":{"o/r":[\n\t"%s",\n\t"%s"\n]},"z":[1, 2]}\n' \
    "$S/a/repo" "$S/a/repo" "$S/a/repo2" "$S/a/repo" "$S/a/repo2" > "$CONFIG"
cp "$CONFIG" "$S/config.orig"
cp "$OTHER/s3.jsonl" "$S/s3.orig"
old_time "$OLD/s1.jsonl" "$OLD/s1/subagents/agent-1.jsonl" "$OLD_SUB/s2.jsonl"
run 0 -m a/repo b
ok "repository moved" [ -d b/repo/sub ]
ok "source gone" [ ! -e a/repo ]
ok "summary names the move" has_output "^$S/a/repo → $S/b/repo\$"
ok "summary names the session directory" has_output "session directory: $(enc "$S/a/repo") → $(enc "$S/b/repo")\$"
ok "old session directory gone" [ ! -e "$OLD" ]
ok "subdirectory sessions gone" [ ! -e "$OLD_SUB" ]
ok "session file moved" [ -f "$NEW/s1.jsonl" ]
ok "subdirectory sessions moved" [ -f "$NEW_SUB/s2.jsonl" ]
ok "memory moved" [ -f "$NEW/memory/MEMORY.md" ]
ok "tool results moved" [ -f "$NEW/s1/tool-results/x.txt" ]
ok "cwd rewritten" contains "$NEW/s1.jsonl" "\"cwd\":\"$S/b/repo\""
ok "cwd below the project rewritten" contains "$NEW/s1.jsonl" "\"cwd\":\"$S/b/repo/sub\""
ok "cwd outside the project kept" contains "$NEW/s1.jsonl" '"cwd":"/elsewhere"'
ok "nested cwd kept" contains "$NEW/s1.jsonl" "\"message\":{\"cwd\":\"$S/a/repo\"}"
ok "relocatedCwd rewritten" contains "$NEW/s1.jsonl" "\"relocatedCwd\":\"$S/b/repo\""
ok "persistedOutputPath rewritten" contains "$NEW/s1.jsonl" "\"persistedOutputPath\":\"$NEW/s1/tool-results/x.txt\""
ok "cut last line kept" [ "$(tail -c 20 "$NEW/s1.jsonl")" = "$(printf '{"cwd":"%s"' "$S/a/repo" | tail -c 20)" ]
ok "subagent rewritten" contains "$NEW/s1/subagents/agent-1.jsonl" "\"cwd\":\"$S/b/repo/sub\""
ok "subdirectory session rewritten" contains "$NEW_SUB/s2.jsonl" "\"cwd\":\"$S/b/repo/sub\""
ok "repo2 sessions stay" cmp -s "$OTHER/s3.jsonl" "$S/s3.orig"
ok "session time kept" kept_time "$NEW/s1.jsonl"
ok "subagent time kept" kept_time "$NEW/s1/subagents/agent-1.jsonl"
ok "subdirectory session time kept" kept_time "$NEW_SUB/s2.jsonl"
ok "projects key moved" contains "$CONFIG" "\"$S/b/repo\":{\"t\":1}"
ok "projects subdirectory key moved" contains "$CONFIG" "\"$S/b/repo/sub\":{}"
ok "projects repo2 key kept" contains "$CONFIG" "\"$S/a/repo2\":{}"
ok "githubRepoPaths moved, layout kept" contains "$CONFIG" "[
	\"$S/b/repo\",
	\"$S/a/repo2\"
]"
ok "rest of .claude.json kept" contains "$CONFIG" '"z":[1, 2]}'
ok ".claude.json.bak is the old file" cmp -s "$CONFIG.bak" "$S/config.orig"

# Several sources: each on its own, one failure does not stop the rest,
# and .claude.json.bak is the file from before the first change.
scenario many
mkdir -p x/one x/two dest
session "$PROJ/$(enc "$S/x/one")/s.jsonl" "$S/x/one"
session "$PROJ/$(enc "$S/x/two")/s.jsonl" "$S/x/two"
printf '{"projects":{"%s":{},"%s":{}}}\n' "$S/x/one" "$S/x/two" > "$CONFIG"
cp "$CONFIG" "$S/config.orig"
run 1 -m x/one x/missing x/two dest
ok "missing source reported" has_output "there is no directory “$S/x/missing”"
ok "first source moved" [ -d dest/one ]
ok "last source moved" [ -d dest/two ]
ok "first sessions moved" [ -f "$PROJ/$(enc "$S/dest/one")/s.jsonl" ]
ok "last sessions moved" [ -f "$PROJ/$(enc "$S/dest/two")/s.jsonl" ]
ok "both keys moved" contains "$CONFIG" "{\"$S/dest/one\":{},\"$S/dest/two\":{}}"
ok ".claude.json.bak made once" cmp -s "$CONFIG.bak" "$S/config.orig"

# Merging into an existing session directory: nothing is overwritten.
scenario merge
mkdir -p m/old
OLD=$PROJ/$(enc "$S/m/old")
NEW=$PROJ/$(enc "$S/m/new")
session "$OLD/s1.jsonl" "$S/m/old"
session "$OLD/s2.jsonl" "$S/m/old"
mkdir -p "$OLD/memory" "$NEW/memory"
echo old > "$OLD/memory/MEMORY.md"
session "$NEW/s1.jsonl" "$S/m/new"
echo new > "$NEW/memory/other.md"
cp "$OLD/s1.jsonl" "$S/s1.old"
cp "$NEW/s1.jsonl" "$S/s1.new"
printf '{"projects":{"%s":{"old":1},"%s":{"new":1}}}\n' "$S/m/old" "$S/m/new" > "$CONFIG"
cp "$CONFIG" "$S/config.orig"
run 1 -m m/old m/new
ok "merge reported" has_output "merged with the existing one"
ok "conflict reported" has_output "“$(enc "$S/m/old")/s1.jsonl” stays in the old session directory"
ok "key conflict reported" has_output "already has an entry for “$S/m/new”"
ok "repository moved" [ -d m/new ]
ok "new file moved" [ -f "$NEW/s2.jsonl" ]
ok "new file rewritten" contains "$NEW/s2.jsonl" "\"cwd\":\"$S/m/new\""
ok "memory merged" [ -f "$NEW/memory/MEMORY.md" ]
ok "existing memory kept" [ -f "$NEW/memory/other.md" ]
ok "existing file not overwritten" cmp -s "$NEW/s1.jsonl" "$S/s1.new"
ok "conflicting file stays as it was" cmp -s "$OLD/s1.jsonl" "$S/s1.old"
ok "old directory keeps only the conflict" [ "$(ls -A "$OLD")" = s1.jsonl ]
ok "conflicting key stays" cmp -s "$CONFIG" "$S/config.orig"
ok "no .claude.json.bak without a change" [ ! -e "$CONFIG.bak" ]

# Fix after a manual move, and the refusals.
scenario fix
mkdir -p f/old/sub
session "$PROJ/$(enc "$S/f/old")/s.jsonl" "$S/f/old"
session "$PROJ/$(enc "$S/f/old/sub")/s.jsonl" "$S/f/old/sub"
mkdir -p "$PROJ/$(enc "$S/f/old")/memory"
printf '{"projects":{"%s":{}}}\n' "$S/f/old" > "$CONFIG"
mv f/old f/new
snapshot "$S" > "$WORK/fix.before"
run 1 -F f/new f/other
ok "refused while the old path exists" has_output "“$S/f/new” still exists"
run 1 -F f/old f/nowhere
ok "refused without the new path" has_output "there is no directory “$S/f/nowhere”"
snapshot "$S" > "$WORK/fix.after"
ok "refusals change nothing" cmp -s "$WORK/fix.before" "$WORK/fix.after"
run 0 -F f/old f/new
ok "summary says sessions only" has_output "(sessions only)"
ok "sessions moved" contains "$PROJ/$(enc "$S/f/new")/s.jsonl" "\"cwd\":\"$S/f/new\""
ok "subdirectory sessions moved" contains "$PROJ/$(enc "$S/f/new/sub")/s.jsonl" "\"cwd\":\"$S/f/new/sub\""
ok "memory moved" [ -d "$PROJ/$(enc "$S/f/new")/memory" ]
ok "old session directory gone" [ ! -e "$PROJ/$(enc "$S/f/old")" ]
ok "projects key moved" contains "$CONFIG" "\"$S/f/new\":{}"

# A directory with only memory/ has no cwd: its name decides (project root only).
scenario memory
mkdir -p r/repo
mkdir -p "$PROJ/$(enc "$S/r/repo")/memory" "$PROJ/$(enc "$S/r/repo/sub")/memory"
run 0 -m r/repo r/moved
ok "memory-only directory moved" [ -d "$PROJ/$(enc "$S/r/moved")/memory" ]
ok "subdirectory without cwd stays" [ -d "$PROJ/$(enc "$S/r/repo/sub")/memory" ]

# A symlink to a directory with a space (as iCloud's ~/Documents): the
# sessions under the logical path and under the physical path both move,
# each to its own variant of the new path.
scenario symlink
REAL="$S/Mobile Documents/Dev"
mkdir -p "$REAL/repo"
ln -s "Mobile Documents/Dev" Dev
session "$PROJ/$(enc "$S/Dev/repo")/s.jsonl" "$S/Dev/repo"
session "$PROJ/$(enc "$REAL/repo")/s.jsonl" "$REAL/repo"
printf '{"projects":{"%s":{}},"githubRepoPaths":{"o/r":["%s"]}}\n' "$S/Dev/repo" "$REAL/repo" > "$CONFIG"
cd "$S/Dev" || exit 1
run 0 -m repo moved
cd "$S" || exit 1
ok "repository moved" [ -d "$REAL/moved" ]
ok "logical sessions moved" contains "$PROJ/$(enc "$S/Dev/moved")/s.jsonl" "\"cwd\":\"$S/Dev/moved\""
ok "physical sessions moved" contains "$PROJ/$(enc "$REAL/moved")/s.jsonl" "\"cwd\":\"$REAL/moved\""
ok "logical key moved" contains "$CONFIG" "\"$S/Dev/moved\":{}"
ok "physical githubRepoPaths moved" contains "$CONFIG" "[\"$REAL/moved\"]"

# A long path gets a cut name with a hash, like Claude Code makes it.
scenario long
LONG=$S/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa/bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb/cccccccccccccccccccccccccccccccccccccccccccccccccc/dddddddddddddddddddddddddddddddddddddddddddddddddd
mkdir -p "$LONG" short
session "$PROJ/$(enc "$S/short")/s.jsonl" "$S/short"
run 0 -m short "$LONG/repo"
PREFIX=$(enc "$LONG/repo" | cut -c 1-200)
ok "long name with a hash" [ "$(ls "$PROJ" | grep -c "^$PREFIX-[0-9a-z]*\$")" -eq 1 ]
ok "long session rewritten" contains "$PROJ/$PREFIX"-*/s.jsonl "\"cwd\":\"$LONG/repo\""

# -n plans and changes nothing, not even times.
scenario dry
mkdir -p d/repo e
OLD=$PROJ/$(enc "$S/d/repo")
session "$OLD/s.jsonl" "$S/d/repo" "$S/d/repo/x"
mkdir -p "$PROJ/$(enc "$S/e/repo")"
session "$PROJ/$(enc "$S/e/repo")/t.jsonl" "$S/e/repo"
printf '{"projects":{"%s":{}},"githubRepoPaths":{"o/r":["%s","%s"]}}\n' "$S/d/repo" "$S/d/repo" "$S/e/repo" > "$CONFIG"
snapshot "$S" > "$WORK/dry.before"
touch "$WORK/dry.stamp"
run 0 -m -n d/repo e
ok "plan counts the session fields" has_output "^    $(enc "$S/d/repo")/s.jsonl: cwd ×2\$"
ok "plan shows the projects key" has_output "^    ~/.claude/.claude.json: projects “$S/d/repo” → “$S/e/repo”\$"
ok "plan shows the repeated element" has_output "githubRepoPaths\\[\"o/r\"\\]\\[0\\] “$S/d/repo” goes"
ok "plan shows the merge" has_output "merged with the existing one"
ok "plan ends with the reminder" has_output "^Nothing has changed"
run 0 -Fn d/gone d/repo
snapshot "$S" > "$WORK/dry.after"
ok "-n changes no file" cmp -s "$WORK/dry.before" "$WORK/dry.after"
ok "-n touches no time" [ -z "$(find "$S" -newer "$WORK/dry.stamp")" ]

# csm -l follows a move, and finds the project orphaned once it is gone.
scenario list
mkdir -p a/repo b
session "$PROJ/$(enc "$S/a/repo")/s.jsonl" "$S/a/repo"
run 0 -l
ok "active before the move" has_output "^active .*  $S/a/repo\$"
run 0 -m a/repo b
run 0 -l
ok "listed under the new path" has_output "^active .*  $S/b/repo\$"
ok "old path no longer listed" lacks_output "$S/a/repo"
rm -rf b/repo
run 0 -lo
ok "orphaned once the repository is gone" has_output "^orphaned .*  $S/b/repo\$"
run 0 -s "$S/b/repo"
ok "details of the orphan" has_output "^State: orphaned\$"

# csm -r moves session directories to the trash, csm -u puts them back as
# they were: files, times and the projects entry of an orphaned project.
scenario trash
XDG_DATA_HOME=$HOME/.local/share
export XDG_DATA_HOME
TRASH=$(trash_dir)
mkdir -p live
GONE=$PROJ/$(enc "$S/gone")
GONE_SUB=$PROJ/$(enc "$S/gone/sub")
LIVE=$PROJ/$(enc "$S/live")
session "$GONE/s.jsonl" "$S/gone"
session "$GONE/s/subagents/agent-1.jsonl" "$S/gone/sub"
mkdir -p "$GONE/memory"
echo note > "$GONE/memory/MEMORY.md"
echo outside > "$S/outside"
ln -s "$S/outside" "$GONE/memory/link"
session "$GONE_SUB/t.jsonl" "$S/gone/sub"
session "$LIVE/u.jsonl" "$S/live"
old_time "$GONE/s.jsonl" "$GONE/s/subagents/agent-1.jsonl" "$LIVE/u.jsonl"
printf '{\n  "projects": {\n    "%s": {\n      "allowedTools": []\n    },\n    "%s": {},\n    "%s": {\n      "t": 1\n    }\n  },\n  "z": 1\n}\n' \
    "$S/live" "$S/gone/sub" "$S/gone" > "$CONFIG"
cp "$CONFIG" "$S/config.orig"
snapshot "$GONE" > "$WORK/trash.gone"
snapshot "$S" > "$WORK/trash.before"
run 0 -rn "$S/gone"
ok "plan names the directory and its state" has_output "^to the trash: $(enc "$S/gone") ($S/gone, orphaned)\$"
ok "plan names the projects entry" has_output "entry “$S/gone” goes along\$"
ok "subdirectory sessions not in the plan" lacks_output "$(enc "$S/gone/sub")"
snapshot "$S" > "$WORK/trash.after"
ok "-n changes nothing" cmp -s "$WORK/trash.before" "$WORK/trash.after"
run 0 -ry "$S/gone" -- "$(enc "$S/live")"
ok "orphan's sessions gone" [ ! -e "$GONE" ]
ok "active project's sessions gone" [ ! -e "$LIVE" ]
ok "subdirectory sessions stay" [ -f "$GONE_SUB/t.jsonl" ]
ok "repository never removed" [ -d live ]
ok "orphan's projects entry gone" lacks "$CONFIG" "\"$S/gone\""
ok "active project's entry stays" contains "$CONFIG" "\"$S/live\""
ok "subdirectory entry stays" contains "$CONFIG" "\"$S/gone/sub\": {}
  }"
ok ".claude.json.bak is the old file" cmp -s "$CONFIG.bak" "$S/config.orig"
ok "two entries in the trash" [ "$(ls "$TRASH" | wc -l)" -eq 2 ]
ok "summary names the entry" has_output "^  in the trash as [0-9]\{8\}T[0-9]\{6\}Z$(enc "$S/gone")\$"
ENTRY=$(ls "$TRASH" | grep -- "$(enc "$S/gone")\$")
ENTRY_LIVE=$(ls "$TRASH" | grep -- "$(enc "$S/live")\$")
ok "metadata keeps the projects entry" contains "$TRASH/$ENTRY/meta.json" '"projectsEntry": {
      "t": 1
    }'
run 0 -u
ok "trash lists the entries" has_output "^$ENTRY  .*  $S/gone\$"
ok "trash lists the active project" has_output "^$ENTRY_LIVE  .*  $S/live\$"
ok "trash shows its size" has_output "in total in “~/"
run 0 -un "$ENTRY"
ok "restore plan names the entry" has_output "^$ENTRY → $(enc "$S/gone")\$"
ok "restore -n keeps the entry" [ -d "$TRASH/$ENTRY" ]
run 0 -u "$ENTRY"
snapshot "$GONE" > "$WORK/trash.back"
ok "sessions back as they were" cmp -s "$WORK/trash.gone" "$WORK/trash.back"
ok "session time kept" kept_time "$GONE/s.jsonl"
ok "symlink back" [ -L "$GONE/memory/link" ]
ok ".claude.json back as it was" cmp -s "$CONFIG" "$S/config.orig"
ok "restored entry leaves the trash" [ ! -e "$TRASH/$ENTRY" ]

# Claude Code made a new session directory and a projects entry meanwhile:
# nothing is overwritten, what is left stays in the trash.
mkdir -p "$LIVE"
session "$LIVE/u.jsonl" "$S/live" "$S/live"
cp "$LIVE/u.jsonl" "$S/u.new"
run 1 -u "$ENTRY_LIVE"
ok "merge reported" has_output "merged with the existing one"
ok "kept file reported" has_output "u.jsonl” stays in the trash"
ok "existing file not overwritten" cmp -s "$LIVE/u.jsonl" "$S/u.new"
ok "kept file stays in the trash" [ -f "$TRASH/$ENTRY_LIVE/$(enc "$S/live")/u.jsonl" ]
run 0 -ry "$S/gone"
ENTRY=$(ls "$TRASH" | grep -- "$(enc "$S/gone")\$")
printf '{"projects":{"%s":{"new":1}}}\n' "$S/gone" > "$CONFIG"
cp "$CONFIG" "$S/config.new"
run 1 -u "$ENTRY"
ok "key conflict reported" has_output "already has an entry for “$S/gone”, so the entry from the trash stays"
ok "sessions back despite the key" [ -f "$GONE/s.jsonl" ]
ok "existing key kept" cmp -s "$CONFIG" "$S/config.new"
ok "entry stays for its projects entry" contains "$TRASH/$ENTRY/meta.json" '"projectsKey"'

# Emptying deletes for good, but never what a symlink points to.
run 0 -ry "$S/gone"
snapshot "$S" > "$WORK/empty.before"
run 0 -En
ok "-En lists the entries" has_output "^for good: $ENTRY_LIVE ("
snapshot "$S" > "$WORK/empty.after"
ok "-En deletes nothing" cmp -s "$WORK/empty.before" "$WORK/empty.after"
run 0 -Ey "$ENTRY_LIVE"
ok "named entry deleted" [ ! -e "$TRASH/$ENTRY_LIVE" ]
ok "other entries stay" [ "$(ls "$TRASH" | wc -l)" -eq 2 ]
run 0 -Ey
ok "trash empty" [ -z "$(ls "$TRASH")" ]
ok "symlink target stays" [ -f "$S/outside" ]
run 0 -u
ok "empty trash says so" has_output "^The trash is empty\.\$"
unset XDG_DATA_HOME

# csm -P forgets githubRepoPaths that are gone, and only those: a path
# behind a dangling symlink may be on a disk that is not connected, and the
# rest of .claude.json stays byte for byte.
scenario prune
mkdir -p "$S/live"
ln -s "$S/nowhere" "$S/link"
printf '{\n  "numStartups": 2,\n  "githubRepoPaths": {\n    "o/r": [\n      "%s",\n      "%s",\n      "%s"\n    ],\n    "o/s": [\n      "%s"\n    ]\n  }\n}\n' \
    "$S/gone" "$S/live" "$S/link/repo" "$S/gone2" > "$CONFIG"
cp "$CONFIG" "$S/config.orig"
run 0 -Pn
ok "plan names both" has_output "goes: $S/gone2 (o/s)"
ok "unavailable stays" has_output "stays: $S/link/repo (o/r)"
ok "-n changes nothing" cmp -s "$CONFIG" "$S/config.orig"
run 0 -Py o/r
printf '{\n  "numStartups": 2,\n  "githubRepoPaths": {\n    "o/r": [\n      "%s",\n      "%s"\n    ],\n    "o/s": [\n      "%s"\n    ]\n  }\n}\n' \
    "$S/live" "$S/link/repo" "$S/gone2" > "$S/config.want"
ok "only the gone path of o/r goes" cmp -s "$CONFIG" "$S/config.want"
ok ".bak is the file from before" cmp -s "$CONFIG.bak" "$S/config.orig"
run 0 -Py
ok "o/s gone too" contains "$CONFIG" '"o/s": []'
run 0 -Py
ok "nothing more to forget" has_output "No saved GitHub repository path is missing"

# Another file system: rename gives EXDEV and /bin/mv takes over, for the
# repository (4.1) and for the trash and back (4.6). A small disk image,
# mounted below WORKDIR and hidden from the Finder, is the other volume.
# Without hdiutil (Linux) a directory on another file system named by
# CSM_TEST_OTHER_FS (for example the tmpfs /dev/shm) holds it;
# without both the scenario is skipped.
scenario exdev
XDG_DATA_HOME=$HOME/.local/share
VOL=
if [ -n "$CSM_TEST_OTHER_FS" ]
then
	VOL=$CSM_TEST_OTHER_FS/csm-exdev
	rm -rf "$VOL"
	mkdir "$VOL" || exit 1
	trap 'rm -rf "$VOL"' EXIT INT TERM
elif command -v hdiutil > /dev/null 2>&1 &&
    hdiutil create -quiet -size 16m -fs HFS+ -volname csm-test "$S/vol.dmg" &&
    mkdir -p "$S/vol" &&
    hdiutil attach -quiet -nobrowse -noautoopen -mountpoint "$S/vol" "$S/vol.dmg"
then
	VOL=$S/vol
	trap 'cd "$WORK" && hdiutil detach -quiet "$VOL"' EXIT INT TERM
fi
if [ -n "$VOL" ]
then
	ok "a file system of its own" [ "$(device "$S")" != "$(device "$VOL")" ]

	mkdir -p a/repo/sub
	echo text > a/repo/sub/file
	# Only macOS has the xattr tool; Linux lacks it without the attr package.
	XATTR=
	if command -v xattr > /dev/null 2>&1
	then
		XATTR=yes
		xattr -w org.csm.test kept a/repo/sub/file
	fi
	session "$PROJ/$(enc "$S/a/repo")/s.jsonl" "$S/a/repo"
	old_time "$PROJ/$(enc "$S/a/repo")/s.jsonl"
	printf '{"projects":{"%s":{}}}\n' "$S/a/repo" > "$CONFIG"
	run 0 -m a/repo "$VOL"
	ok "repository on the other volume" [ -f "$VOL/repo/sub/file" ]
	ok "source gone" [ ! -e a/repo ]
	if [ -n "$XATTR" ]
	then
		ok "extended attribute kept" [ "$(xattr -p org.csm.test "$VOL/repo/sub/file")" = kept ]
	fi
	ok "sessions follow" contains "$PROJ/$(enc "$VOL/repo")/s.jsonl" "\"cwd\":\"$VOL/repo\""
	ok "session time kept" kept_time "$PROJ/$(enc "$VOL/repo")/s.jsonl"
	ok "projects key follows" contains "$CONFIG" "\"$VOL/repo\":{}"

	# Claude Code's data on the volume, the trash in HOME on the disk.
	CLAUDE_CONFIG_DIR=$VOL/.claude
	PROJ=$CLAUDE_CONFIG_DIR/projects
	CONFIG=$CLAUDE_CONFIG_DIR/.claude.json
	GONE=$PROJ/$(enc "$S/gone")
	TRASH=$(trash_dir)
	session "$GONE/s.jsonl" "$S/gone"
	mkdir -p "$GONE/memory"
	echo note > "$GONE/memory/MEMORY.md"
	old_time "$GONE/s.jsonl"
	printf '{"projects":{"%s":{"t":1}}}\n' "$S/gone" > "$CONFIG"
	cp "$CONFIG" "$S/config.orig"
	snapshot "$GONE" > "$WORK/exdev.gone"
	run 0 -ry "$S/gone"
	ENTRY=$(ls "$TRASH" | grep -- "$(enc "$S/gone")\$")
	ok "session directory left the volume" [ ! -e "$GONE" ]
	ok "session directory in the trash" [ -f "$TRASH/$ENTRY/$(enc "$S/gone")/s.jsonl" ]
	ok "time kept in the trash" kept_time "$TRASH/$ENTRY/$(enc "$S/gone")/s.jsonl"
	ok "projects entry gone" lacks "$CONFIG" "\"$S/gone\""
	run 0 -u "$ENTRY"
	snapshot "$GONE" > "$WORK/exdev.back"
	ok "sessions back as they were" cmp -s "$WORK/exdev.gone" "$WORK/exdev.back"
	ok "session time kept" kept_time "$GONE/s.jsonl"
	ok ".claude.json back as it was" cmp -s "$CONFIG" "$S/config.orig"
	ok "restored entry leaves the trash" [ ! -e "$TRASH/$ENTRY" ]

	cd "$WORK" || exit 1
	if [ -n "$CSM_TEST_OTHER_FS" ]
	then
		ok "volume emptied" rm -rf "$VOL"
	else
		ok "volume detached" hdiutil detach -quiet "$VOL"
	fi
	trap - EXIT INT TERM
else
	echo "integration: no second volume (hdiutil or CSM_TEST_OTHER_FS), the other file system is not tested."
fi

echo "integration: $CHECKS checks, $FAILURES failed"
[ "$FAILURES" -eq 0 ]
